/** `velar:browser` 的模型面：模型 import 的模块名、放出去的方法、生成的完整声明（与 baselines/code-surface/browser.d.ts 是同一份）、代码模版（template.js）。 */
export const VelarBrowserModule: { readonly specifier: string; readonly namespace: string; readonly methods: readonly string[]; readonly declarations: string; readonly template: string } = Object.freeze({
  specifier: 'velar:browser',
  namespace: 'browser',
  methods: Object.freeze(['open', 'leave', 'state', 'show', 'tabs', 'switchTab', 'inspect', 'query', 'screenshot', 'evaluate', 'media', 'click', 'fill', 'select', 'check', 'hover', 'focus', 'clear', 'selectText', 'scrollIntoView', 'goto', 'back', 'forward', 'reload', 'scroll', 'type', 'press', 'mouseMove', 'clickAt', 'drag', 'upload', 'waitForSelector', 'waitForText', 'waitForUrl', 'waitForFunction', 'waitForLoad', 'wait', 'events', 'waitForEvent', 'handleDialog', 'handleDownload', 'handlePermission', 'table', 'list', 'paginate', 'content', 'download', 'savePdf']),
  declarations: "declare module 'velar:browser' {\n  /**\n   * 浏览器：打开网站、看页面、按元素或坐标动手、等页面到位、处理弹窗下载与权限、把表格列表正文取出来、下载与导出。\n   * 先 open 进站点，其余要页面的操作没进站点时抛 BROWSER_SITE_NOT_OPEN。页面是异步的：动完用 waitFor 那几个等到位再读，别靠重试。\n   * 元素写法：inspect、标注截图给的 ref（如 @e3:g2，原样传回；新的一次 inspect 或标注截图之后旧 ref 作废），或 CSS selector，或结果里的 target。\n   * 站点工作区是这个网站的私有目录：截图、下载、PDF 都落在那里，路径一律相对它，出不去。\n   * 控制台、网络、存储、性能、录屏、页面条件与用户脚本在 velar:devtools。\n   */\n\n  /** 打开一个网站并进入它的站点：url 最多 2048 个字符，不带协议按 https:// 补全，localhost 也行。 */\n  interface BrowserOpenInput {\n    url: string\n  }\n\n  /** 进站的结果：站点工作区在哪（workspaceRoot），以及落地后的页面状态。 */\n  interface BrowserOpened {\n    site: BrowserSiteContext\n    page: BrowserPageState\n  }\n\n  /** 当前状态：没进站点时 active 为假、其余字段都没有；进了站点时带着站点与页面状态。 */\n  interface BrowserState {\n    active: boolean\n    site?: BrowserSiteContext\n    page?: BrowserPageState\n  }\n\n  /** 受控页面的窗口状态：visible 是用户看不看得见，driverKind 是内嵌页面（webview）还是外部浏览器（external），以及地址、标题、能不能前进后退。 */\n  interface BrowserPageWindowState {\n    active: boolean\n    visible: boolean\n    driverKind: 'webview' | 'external'\n    url: string | null\n    title: string | null\n    canGoBack: boolean\n    canGoForward: boolean\n    /** 模型显式设置的 CSS viewport；null 表示跟随浏览器工作区可用尺寸。 */\n    viewport: BrowserViewportOptions | null\n  }\n\n  /** 标签页列表：activeTargetId 是当前在操作的那一页。 */\n  interface BrowserPageTargetsResult {\n    driverKind: 'webview' | 'external'\n    activeTargetId: string | null\n    targets: BrowserPageTargetInfo[]\n    capturedAt: number\n  }\n\n  /** 切到外部浏览器的另一个标签页：targetId 取自 tabs() 结果里的 targets[].id。 */\n  interface BrowserSwitchTabInput {\n    targetId: string\n  }\n\n  /** 切换之后：target 是现在在操作的那一页，targets 是全部标签页。 */\n  interface BrowserSwitchPageTargetResult {\n    driverKind: 'webview' | 'external'\n    activeTargetId: string | null\n    target: BrowserPageTargetInfo\n    targets: BrowserPageTargetInfo[]\n    url: string\n    title: string | null\n    capturedAt: number\n  }\n\n  /**\n   * 看页面：maxTextChars 是正文最多交回多少字符（最多 100000），includeHtml 为真再带上 HTML（maxHtmlChars 最多 100000），\n   * maxElements 是可交互元素最多几个（最多 400），ignoreSelectors 是先排除掉的噪音子树（导航、cookie 提示条、广告，最多 50 个 selector）。\n   * 不给就取到上限。\n   */\n  interface BrowserInspectInput {\n    maxTextChars?: number\n    includeHtml?: boolean\n    maxHtmlChars?: number\n    maxElements?: number\n    ignoreSelectors?: string[]\n  }\n\n  /**\n   * 看页面的结果：text 是正文（textTruncated 为真表示被截断），html 只在 includeHtml 时有；headings、links、actions（可以点的）、formFields（表单字段）各带 target。\n   * login 是登录墙的启发式检测，loginGate 只在这次停下来问过用户时出现（用户登录完之后这里已经是重读过的页面）。\n   */\n  interface BrowserPageInspection {\n    url: string\n    title: string\n    metaDescription: string | null\n    text: string\n    textTruncated: boolean\n    html?: string\n    htmlTruncated?: boolean\n    headings: BrowserPageHeading[]\n    links: BrowserPageLink[]\n    actions: BrowserPageAction[]\n    formFields: BrowserPageFormField[]\n    snapshot?: BrowserPageSnapshot\n    /** 登录墙的启发式检测：与截图同一份判据，随看页面的脚本顺带算出，不另跑一次脚本。 */\n    login?: BrowserLoginDetection\n    /** 本次检查是否触发过登录墙门控；缺席 = 没触发（不是「没检测」）。 */\n    loginGate?: BrowserLoginGateRecord\n    capturedAt: number\n  }\n\n  /**\n   * 按 CSS selector 找元素：selector 最多 1000 个字符，一层同源 iframe 里的元素写成 `iframe[name=\"x\"] >> .inner`；\n   * attributes 是额外要读的属性名（最多 20 个，每个最多 80 个字符），includeHtml 为真再带上每个元素的 HTML；\n   * limit 最多几个元素（最多 100），maxTextChars、maxHtmlChars 是每个元素的文本与 HTML 最多多少字符（最多 20000、50000）。不给就取到上限。\n   */\n  interface BrowserQueryInput {\n    selector: string\n    attributes?: string[]\n    includeHtml?: boolean\n    limit?: number\n    maxTextChars?: number\n    maxHtmlChars?: number\n  }\n\n  /** query 的结果：count 是一共匹配几个，elements 是交回的那几个；selectorError 是 selector 写错时的说明。 */\n  interface BrowserElementQueryResult {\n    url: string\n    selector: string\n    selectorError: string | null\n    count: number\n    limit: number\n    elements: BrowserQueriedElement[]\n    capturedAt: number\n  }\n\n  /**\n   * 截图：图交给你看，原图落进站点工作区（path 是工作区里的相对路径，最多 180 个字符，不给就按时间命名）。\n   * 缺省截当前视口；fullPage 为真截整页（单边最多 32000 像素），region 只截一块（与 fullPage 同时给时以 region 为准）。\n   * annotate 为真先给可交互元素画上编号（最多 120 个），legend 里给每个编号的 target，能直接交给 click 这类操作。\n   * width、height 是截图前把视口设成多大（宽 320 到 3840，高 240 到 2160）。截图前缺省会等一小会儿网络空闲与页面不再变（动画、骨架屏）：\n   * waitForNetworkIdle 给数字是网络空闲多少毫秒（100 到 5000），两个都可以传 false 不等；compareWithPrevious 缺省为真，diff 里说与上一张比变没变。\n   */\n  interface BrowserScreenshotInput {\n    path?: string\n    fullPage?: boolean\n    region?: BrowserScreenshotRegion\n    annotate?: boolean\n    width?: number\n    height?: number\n    waitForNetworkIdle?: boolean | number\n    waitForDomStable?: boolean\n    compareWithPrevious?: boolean\n  }\n\n  /**\n   * 截图的结果：原图落在 path（relativePath 是站点工作区里的相对路径），width、height、bytes 是原图的尺寸与大小；\n   * capture 说截的是页面哪一块，image 是交给你看的那张图，legend 是 annotate 时每个编号元素的说明与 target，\n   * diff 是与上一张的比较，login 是登录墙的启发式检测，loginGate 只在这次停下来问过用户时出现。\n   */\n  interface BrowserScreenshot {\n    path: string\n    relativePath: string\n    width: number\n    height: number\n    bytes: number\n    capture?: BrowserScreenshotCaptureRegion\n    image?: BrowserScreenshotImage\n    legend?: BrowserScreenshotElementLegendItem[]\n    diff?: BrowserScreenshotDiff\n    login?: BrowserLoginDetection\n    loginGate?: BrowserLoginGateRecord\n  }\n\n  /**\n   * 在页面里跑一段 JavaScript：script 最多 20000 个字符。mode 缺省 expression（一个表达式，交回它的值），\n   * function-body 是函数体（多条语句，用 return 交回）。timeoutMs 最多 30000；结果按 JSON 取回，超过 200000 个字符时只回截断标记。\n   */\n  interface BrowserEvaluateInput {\n    script: string\n    mode?: BrowserEvaluateScriptMode\n    timeoutMs?: number\n  }\n\n  /** 脚本的结果：ok 为假时 error 是页面里抛的错；result 是交回的值（按 JSON 取回），resultTruncated 为真时 result 取不全、resultText 是截断的 JSON 文本。 */\n  interface BrowserEvaluateScriptResult {\n    url: string\n    ok: boolean\n    mode: BrowserEvaluateScriptMode\n    result: unknown\n    /** 结果的缩进 JSON 文本，只在 resultTruncated 为真时给出（没截断时 result 就是完整内容，不再重复一份）。 */\n    resultText?: string | null | undefined\n    resultTruncated: boolean\n    error: ({\n      name: string\n      message: string\n      stack: string | null\n    }) | null | undefined\n    durationMs: number\n    capturedAt: number\n  }\n\n  /** 列页面上的图片、视频、音频地址：limit 最多几条（最多 200，不给就取到上限），data: 与 blob: 地址缺省不列。 */\n  interface BrowserMediaInput {\n    limit?: number\n    includeDataUrls?: boolean\n    includeBlobUrls?: boolean\n  }\n\n  /** 页面上的媒体地址：truncated 为真表示超过上限没列全。 */\n  interface BrowserListMediaSourcesResult {\n    url: string\n    items: BrowserMediaSourceItem[]\n    truncated: boolean\n    capturedAt: number\n  }\n\n  /** 点一个元素：waitForNavigation 为真时按完整的导航稳定窗口等（缺省只短暂等一下可能的跳转）。 */\n  interface BrowserClickInput {\n    target: BrowserTarget\n    waitForNavigation?: boolean\n  }\n\n  /**\n   * 按元素动手的结果：matched 为假时 failureReason 说为什么（没找到、点不动、被挡住、没有这个选项），blockedBy 是挡住它的元素；\n   * effect 是动手前后页面的变化（地址、标题、正文），selectedValues、availableOptions 是 select 的结果与可选项，controlState 是动完之后控件的状态。\n   * selectorRecovery 在改用坐标补点时出现，actionEffect 在点中了却没有变化时出现。\n   */\n  interface BrowserActed extends BrowserTargetActionResult {\n    selectorRecovery?: BrowserSelectorRecovery\n    actionEffect?: BrowserActionEffectHint\n  }\n\n  /** 往输入框或可编辑区域写入文字（先清空再写）：value 最多 20000 个字符。 */\n  interface BrowserFillInput {\n    target: BrowserTarget\n    value: string\n  }\n\n  /** 选原生 select 的选项：value 按选项的值或可见文字匹配，多选给数组（最多 50 个，每个最多 1000 个字符）。 */\n  interface BrowserSelectInput {\n    target: BrowserTarget\n    value: string | string[]\n  }\n\n  /** 勾选或取消勾选复选框、单选项：checked 缺省 true。 */\n  interface BrowserCheckInput {\n    target: BrowserTarget\n    checked?: boolean\n  }\n\n  /** 只要一个元素的操作（悬停、聚焦、清空、选中文字、滚到视口里）。 */\n  interface BrowserTargetInput {\n    target: BrowserTarget\n  }\n\n  /** 跳到一个网址：url 最多 2048 个字符。 */\n  interface BrowserGotoInput {\n    url: string\n  }\n\n  /** 导航的结果：navigated 是真的跳了没有，url、title 是落地的页面，canGoBack、canGoForward 是还能不能后退、前进。 */\n  interface BrowserPageNavigationResult {\n    action: BrowserPageNavigationAction\n    navigated: boolean\n    url: string\n    title: string | null\n    canGoBack: boolean\n    canGoForward: boolean\n    capturedAt: number\n  }\n\n  /**\n   * 滚动页面：direction 是 up、down、left、right、top、bottom（缺省 down），amount 是一次滚多少像素（最多 5000）；\n   * 也可以直接给 x、y 偏移（绝对值最多 10000）。\n   */\n  interface BrowserScrollInput {\n    direction?: BrowserPageScrollDirection\n    amount?: number\n    x?: number\n    y?: number\n  }\n\n  /** 滚动之后的位置：scrollX、scrollY 是当前滚动位置，maxScrollX、maxScrollY 是能滚到的最远处（scrollY 等于 maxScrollY 就是到底了）。 */\n  interface BrowserPageScrollResult {\n    url: string\n    scrollX: number\n    scrollY: number\n    maxScrollX: number\n    maxScrollY: number\n    viewportWidth: number\n    viewportHeight: number\n    capturedAt: number\n  }\n\n  /** 在当前焦点处输入文字（真的按键，不直接改 value）：text 最多 20000 个字符。要先点中输入框。 */\n  interface BrowserTypeInput {\n    text: string\n  }\n\n  /** 输入的结果：textLength 是输了几个字符。 */\n  interface BrowserTypeTextResult {\n    url: string\n    textLength: number\n    capturedAt: number\n  }\n\n  /**\n   * 按一个键：key 是 Enter、Escape、Tab、ArrowDown 这类键名或一个字符（最多 80 个字符），组合键写 Control+a 或给 modifiers；\n   * repeat 是连按几次（最多 50），waitForNavigation 为真时按完等可能的跳转。\n   */\n  interface BrowserPressInput {\n    key: string\n    modifiers?: BrowserKeyModifier[]\n    repeat?: number\n    waitForNavigation?: boolean\n  }\n\n  /** 按键的结果：key 是按的键，repeat 是按了几次。 */\n  interface BrowserPressKeyResult {\n    url: string\n    key: string\n    repeat: number\n    capturedAt: number\n  }\n\n  /** 视口里的一个点（CSS 像素，0 到 10000）。 */\n  interface BrowserPointInput {\n    x: number\n    y: number\n  }\n\n  /** 移动鼠标的结果：鼠标现在停在视口里的 x、y。 */\n  interface BrowserMoveMouseResult {\n    url: string\n    x: number\n    y: number\n    capturedAt: number\n  }\n\n  /** 按视口坐标点一下（定位不到元素时的兜底）：button 缺省 left，clickCount 是连击几下（最多 5）。 */\n  interface BrowserClickAtInput {\n    x: number\n    y: number\n    button?: BrowserMouseButton\n    clickCount?: number\n    waitForNavigation?: boolean\n  }\n\n  /** 坐标点击的结果：点在视口里的 x、y，用的哪个键、点了几下。 */\n  interface BrowserClickCoordinatesResult {\n    url: string\n    x: number\n    y: number\n    button: BrowserMouseButton\n    clickCount: number\n    capturedAt: number\n  }\n\n  /** 把一个元素拖到另一个元素上：steps 是拆成几步移动（最多 60）。 */\n  interface BrowserDragInput {\n    source: BrowserTarget\n    target: BrowserTarget\n    steps?: number\n    waitForNavigation?: boolean\n  }\n\n  /** 拖拽的结果：matched 为假时 failureReason 说为什么；startX、startY 到 endX、endY 是拖动的路径。 */\n  interface BrowserDragResult {\n    url: string\n    matched: boolean\n    source: BrowserDragEndpointResult\n    target: BrowserDragEndpointResult\n    startX: number | null\n    startY: number | null\n    endX: number | null\n    endY: number | null\n    steps: number\n    failureReason: BrowserDragFailureReason | null\n    capturedAt: number\n  }\n\n  /** 给 file input 选文件：filePath 是站点工作区里的相对路径（出了工作区一律拒绝），最多 4096 个字符。 */\n  interface BrowserUploadInput {\n    target: BrowserTarget\n    filePath: string\n  }\n\n  /** 上传的结果：matched 为假表示没找到那个 file input，files 是塞进去的文件。 */\n  interface BrowserUploadFileResult {\n    matched: boolean\n    selector: string | null\n    files: string[]\n    capturedAt: number\n  }\n\n  /** 等一个 selector 到某个状态：state 缺省 visible，timeoutMs 最多 60000。 */\n  interface BrowserWaitForSelectorInput {\n    selector: string\n    state?: BrowserWaitForSelectorState\n    timeoutMs?: number\n  }\n\n  /** 等 selector 的结果：matched 为假表示等到超时也没到，count 是匹配几个，target 是第一个匹配的元素。 */\n  interface BrowserWaitForSelectorResult {\n    url: string\n    selector: string\n    state: BrowserWaitForSelectorState\n    matched: boolean\n    visible: boolean\n    count: number\n    elapsedMs: number\n    target: BrowserElementTargetHint | null\n    capturedAt: number\n  }\n\n  /** 等页面正文里出现一段文字：text 最多 5000 个字符，timeoutMs 最多 60000。 */\n  interface BrowserWaitForTextInput {\n    text: string\n    timeoutMs?: number\n  }\n\n  /** 等页面的结果：matched 为真表示等到了，timedOut 为真表示等到超时；functionResult 是 waitForFunction 的表达式最后的值，elapsedMs 是实际等了多久。 */\n  interface BrowserPageWaitResult {\n    url: string\n    loadState: 'loading' | 'interactive' | 'complete'\n    requestedLoadState: BrowserPageWaitLoadState | null\n    urlPattern: string | null\n    functionExpression: string | null\n    functionResult: unknown\n    text: string | null\n    matched: boolean\n    durationMs: number\n    timeoutMs: number\n    elapsedMs: number\n    timedOut: boolean\n    capturedAt: number\n  }\n\n  /** 等地址变成某个样子：url 是完整地址或带 * 的通配（最多 2048 个字符），timeoutMs 最多 60000。 */\n  interface BrowserWaitForUrlInput {\n    url: string\n    timeoutMs?: number\n  }\n\n  /** 等页面里一个表达式变成真：expression 最多 5000 个字符，timeoutMs 最多 60000。 */\n  interface BrowserWaitForFunctionInput {\n    expression: string\n    timeoutMs?: number\n  }\n\n  /** 等页面加载到某个状态：state 缺省 load，timeoutMs 最多 60000。 */\n  interface BrowserWaitForLoadInput {\n    state?: BrowserPageWaitLoadState\n    timeoutMs?: number\n  }\n\n  /** 原地停一会儿：ms 最多 60000。能等具体条件时用 waitFor 那几个。 */\n  interface BrowserWaitInput {\n    ms: number\n  }\n\n  /** 此刻挂着的全部事件。 */\n  interface BrowserPendingEventsResult {\n    pending: BrowserPendingEventSummary[]\n    capturedAt: number\n  }\n\n  /** 等一个挂起事件出现：kind 缺省 download，timeoutMs 缺省 5000、最多 60000。 */\n  interface BrowserWaitForEventInput {\n    kind?: BrowserPendingEventKind\n    timeoutMs?: number\n  }\n\n  /** 等挂起事件的结果：matched 为真时 event 是等到的那个；timedOut 为真是等到超时也没来。pending 是此刻还挂着的全部事件。 */\n  interface BrowserPendingEventWaitResult {\n    matched: boolean\n    timedOut: boolean\n    kind: BrowserPendingEventKind\n    event: BrowserPendingEventSummary | null\n    pending: BrowserPendingEventSummary[]\n    timeoutMs: number\n    elapsedMs: number\n  }\n\n  /** 处理 JS 弹窗：accept 为真是确认、为假是取消；prompt 弹窗用 promptText 填值。eventId 不给就处理最早的那个弹窗。 */\n  interface BrowserDialogInput {\n    eventId?: string\n    accept: boolean\n    promptText?: string\n  }\n\n  /** 弹窗处理的结果：handled 为真表示处理掉了。 */\n  interface BrowserHandleDialogResult {\n    handled: boolean\n    eventId: string\n    accept: boolean\n    promptText: string\n  }\n\n  /** 处理一次下载：给 savePath（站点工作区里的相对路径）就保存到那里，cancel 为真就取消。eventId 不给就处理最早的那个下载。 */\n  interface BrowserDownloadDecisionInput {\n    eventId?: string\n    savePath?: string\n    cancel?: boolean\n  }\n\n  /** 下载处理的结果：savePath 是存到的位置，state 是下载的最终状态。 */\n  interface BrowserHandleDownloadResult {\n    handled: boolean\n    eventId: string\n    action: 'accept' | 'cancel'\n    savePath: string | null\n    state: string | null\n  }\n\n  /** 处理权限请求（定位、通知、剪贴板这类）：grant 为真是允许。eventId 不给就处理最早的那个请求。 */\n  interface BrowserPermissionInput {\n    eventId?: string\n    grant: boolean\n  }\n\n  /** 权限请求处理的结果。 */\n  interface BrowserHandlePermissionResult {\n    handled: boolean\n    eventId: string\n    granted: boolean\n  }\n\n  /** 取一张表：selector 限定在哪张表或哪个容器里找，tableIndex 是第几张（从 0 起，最多 50，缺省 0），maxRows 最多几行（最多 2000，不给就取到上限）。 */\n  interface BrowserTableInput {\n    selector?: string\n    tableIndex?: number\n    maxRows?: number\n  }\n\n  /** 取到的表：ok 为假时 error 说为什么（比如页面上没有表格）；tables 是页面上一共几张表，headers 是表头，rows 是各行的文字。 */\n  interface BrowserTable {\n    ok: boolean\n    error: string | null\n    tables: number\n    selector: string | null\n    headers: string[]\n    rows: string[][]\n    url?: string\n  }\n\n  /** 按重复出现的容器取一组条目（搜索结果、商品卡片）：selector 是每一条的容器，maxItems 最多几条（最多 500，不给就取到上限）。 */\n  interface BrowserListInput {\n    selector?: string\n    maxItems?: number\n  }\n\n  /** 取到的一组条目。 */\n  interface BrowserList {\n    ok: boolean\n    selector: string | null\n    items: BrowserListItem[]\n    url?: string\n  }\n\n  /**\n   * 翻页收集列表：每页照 list 取一遍再点下一页，翻不动、内容没变或这页是空的就停。maxPages 缺省 5、最多 20，\n   * maxItemsPerPage 每页最多几条（最多 500），nextPageSelector 是下一页按钮（缺省只认 rel=next 与写明「下一页」「next」的按钮）。先确认当前在第一页。\n   */\n  interface BrowserPaginateInput {\n    selector?: string\n    maxPages?: number\n    maxItemsPerPage?: number\n    nextPageSelector?: string\n  }\n\n  /** 翻页收集的结果：pagesVisited 是翻了几页，items 是各页条目按顺序接起来。 */\n  interface BrowserPaginated {\n    pagesVisited: number\n    items: BrowserListItem[]\n  }\n\n  /** 取正文：format 缺省 markdown（也可以 plain、html），selector 限定范围，ignoreSelectors 先排除的子树，maxChars 最多 200000（不给就取到上限）。 */\n  interface BrowserContentInput {\n    format?: BrowserPageContentFormat\n    selector?: string\n    ignoreSelectors?: string[]\n    maxChars?: number\n  }\n\n  /** 取到的正文：ok 为假表示 selector 没找到东西；truncated 为真表示超过 maxChars 被截断。 */\n  interface BrowserContent {\n    ok: boolean\n    format: BrowserPageContentFormat\n    selector: string | null\n    content: string\n    truncated: boolean\n    url: string\n  }\n\n  /**\n   * 带着当前页面的 cookie 下载一个 http(s) 资源到站点工作区：url 与 savePath 各最多 4096 个字符，单个文件最多 52428800 字节；\n   * referer 不给就用当前页面的地址。blob:、data: 与 DRM 保护的流下不了。\n   */\n  interface BrowserDownloadInput {\n    url: string\n    savePath: string\n    referer?: string\n  }\n\n  /** 下载到站点工作区的文件：path 是绝对路径，relativePath 是工作区里的相对路径，mimeType、bytes、status 是类型、大小与 HTTP 状态。 */\n  interface BrowserFetchResourceResult {\n    url: string\n    path: string\n    relativePath: string\n    mimeType: string | null\n    bytes: number\n    status: number\n    capturedAt: number\n  }\n\n  /** 把当前页面导出成 PDF 落进站点工作区：path 是相对路径，不给就按时间命名。 */\n  interface BrowserSavePdfInput {\n    path?: string\n  }\n\n  /** 导出的 PDF：path 是绝对路径，relativePath 是工作区里的相对路径。 */\n  interface BrowserExportPagePdfResult {\n    url: string\n    path: string\n    relativePath: string\n    bytes: number\n    capturedAt: number\n  }\n\n  /** 站点：url 是进站时的地址，workspaceRoot 是这个站点的工作区（截图、下载、PDF 都落在这里），legacyWorkspaceRoots 是只读的旧工作区（读不到时依次往回找）。 */\n  interface BrowserSiteContext {\n    url: string\n    /** 站点工作区根：写入的唯一落点（粒度由宿主定）。 */\n    workspaceRoot: string\n    /**\n     * 只读的历史工作区根（换粒度前留下的资产），按新到旧排列：写只写 workspaceRoot，读不到才依次回退。\n     * 不做一次性搬迁——回退读是幂等的，用户每碰一次旧资产就自然继续可用，新写入自动落到新位置。\n     */\n    legacyWorkspaceRoots?: readonly string[]\n  }\n\n  /**\n   * 页面状态：url、title，loadState 是最近一次加载成没成（loaded、error、unknown），viewport 是用 setViewport 设过的视口（没设是 null），lastNavigationError 是最近一次导航失败的详情。\n   */\n  interface BrowserPageState {\n    /** 当前 URL。 */\n    url: string\n    /** 当前 document.title。 */\n    title: string\n    /** 最近一次加载是否成功。 */\n    loadState: 'loaded' | 'error' | 'unknown'\n    /** 模型显式设置的 CSS viewport。 */\n    viewport: BrowserViewportOptions | null\n    /** 最近一次导航失败详情；成功或未知时为 null。 */\n    lastNavigationError: {\n      url: string\n      errorCode: number\n      errorDescription: string\n      failedAt: number\n    } | null | undefined\n  }\n\n  /** 视口尺寸：width、height 是 CSS 像素，mobile 为真时按手机视口处理。 */\n  interface BrowserViewportOptions {\n    width: number\n    height: number\n    /** 是否启用 Chromium 的移动设备 viewport 语义；缺省保持桌面兼容行为。 */\n    mobile?: boolean\n  }\n\n  /** 一个标签页：id 交给 switchTab，active 为真表示当前在操作它。 */\n  interface BrowserPageTargetInfo {\n    id: string\n    type: 'page'\n    url: string\n    title: string\n    active: boolean\n  }\n\n  /** 页面上的一个标题：level 是级别（1 最高）。 */\n  interface BrowserPageHeading {\n    level: number\n    text: string\n  }\n\n  /** 页面上的一个链接：text、href 与它的 target。 */\n  interface BrowserPageLink {\n    text: string\n    href: string\n    target: BrowserElementTargetHint | null\n  }\n\n  /** 页面上一个可以点的东西：text 是文字，role 是种类，target 交给 click。 */\n  interface BrowserPageAction {\n    text: string\n    role: BrowserPageActionRole\n    target: BrowserElementTargetHint | null\n  }\n\n  /** 页面上的一个表单字段：label 是标签，type 是输入类型，required 是必不必填，target 交给 fill、select、check。 */\n  interface BrowserPageFormField {\n    label: string\n    type: string\n    name: string | null\n    placeholder: string | null\n    required: boolean\n    target: BrowserElementTargetHint | null\n  }\n\n  /** 页面的紧凑文本快照：lines 每行一个元素（带 ref），refCount 是一共几个 ref，truncated 为真表示被截断。 */\n  interface BrowserPageSnapshot {\n    mode: 'compact'\n    source: BrowserPageSnapshotSource\n    lines: string[]\n    refCount: number\n    truncated: boolean\n  }\n\n  /** 登录墙的启发式检测：requiresLogin 为真表示这页像登录、验证或支付页，confidence 是把握（0 到 1），reason 与 signals 说依据。遇到登录墙别自己填账号密码，交给用户。 */\n  interface BrowserLoginDetection {\n    requiresLogin: boolean\n    confidence: number\n    reason: string\n    signals: string[]\n    passwordInputs: number\n    usernameInputs: number\n    loginButtons: number\n    loginLinks: number\n    forms: number\n  }\n\n  /** 这一页停下来问过用户：approved 为真表示用户说已经登录好、可以继续，reason 是结论说明。同一站点在一次会话里只问一次。 */\n  interface BrowserLoginGateRecord {\n    /** 是否真的阻塞并向用户征询过；本记录存在即为 true（缺席表示从未触发门控）。 */\n    prompted: boolean\n    /** 用户是否表示已完成登录并继续。 */\n    approved: boolean\n    /** 触发门控的站点源。 */\n    origin: string | null\n    confidence: number\n    signals: string[]\n    /** 门控结论说明：批准时取检测理由，拒绝时取用户/宿主给的原因。 */\n    reason: string\n    resolvedAt: number\n  }\n\n  /** query 找到的一个元素：tagName、text、attributes、href、value、checked、visible，以及交给 click 这类操作的 target。 */\n  interface BrowserQueriedElement {\n    index: number\n    tagName: string\n    text: string\n    textTruncated: boolean\n    html?: string\n    htmlTruncated?: boolean\n    attributes: Record<string, string>\n    href: string | null\n    value: string | null\n    checked: boolean | null\n    visible: boolean\n    target: BrowserElementTargetHint | null\n  }\n\n  /** 只截页面上的一块：给 selector（截那个元素），或者给完整的 x、y、width、height（页面 CSS 像素，含滚动，最多 20000）。 */\n  type BrowserScreenshotRegion =\n    | { selector: string }\n    | { x: number; y: number; width: number; height: number }\n\n  /** 截的是页面哪一块：mode 是 viewport、full-page、region；x、y、width、height 是那块在页面上的位置（CSS 像素，含滚动），clipped 为真表示超出上限被裁过。 */\n  interface BrowserScreenshotCaptureRegion extends BrowserScreenshotRect {\n    mode: 'viewport' | 'full-page' | 'region'\n    coordinateSpace: 'page-css-px'\n    documentWidth: number\n    documentHeight: number\n    viewport: BrowserScreenshotRect\n    clipped: boolean\n  }\n\n  /** 交给你看的那张图：宽高（像素）、相对原图缩了多少（scale）、页面 CSS 坐标与图上坐标怎么换算（coordinateMap）。 */\n  interface BrowserScreenshotImage {\n    width: number\n    height: number\n    scale: number\n    coordinateMap?: BrowserScreenshotModelCoordinateMap\n  }\n\n  /** 标注截图里的一个编号元素：index 是图上的编号，label、description 说它是什么，target 交给 click 这类操作。 */\n  interface BrowserScreenshotElementLegendItem {\n    index: number\n    label: string\n    role: string | null\n    text: string | null\n    selector: string | null\n    description: string\n    target: BrowserElementTargetHint\n  }\n\n  /** 与上一张截图的比较：changed 是变没变，reason 是 first-capture（第一张）、changed、unchanged，changedRatio 是变了多大比例的像素。 */\n  interface BrowserScreenshotDiff {\n    changed: boolean\n    reason: 'first-capture' | 'changed' | 'unchanged'\n    fingerprint: string\n    previousFingerprint: string | null\n    changedPixels?: number\n    totalPixels?: number\n    changedRatio?: number\n  }\n\n  /** 脚本写法：expression 是一个表达式，function-body 是函数体（用 return 交回）。 */\n  type BrowserEvaluateScriptMode = 'expression' | 'function-body'\n\n  /** 页面上的一个媒体地址：fetchable 为真的可以直接交给 download（blob:、data: 不行），tagName、attribute 说它从哪个元素的哪个属性来。 */\n  interface BrowserMediaSourceItem {\n    kind: BrowserMediaSourceKind\n    url: string\n    fetchable: boolean\n    tagName: string | null\n    attribute: string | null\n    alt: string | null\n    width: number | null\n    height: number | null\n  }\n\n  /** 要操作的元素：字符串以 @ 开头当 ref，其余当 CSS selector；也可以给一份定位线索。 */\n  type BrowserTarget = string | BrowserTargetHint\n\n  /**\n   * 按元素动手的结果：matched 为假时 failureReason 说为什么（not-found 没找到、not-interactable 点不动、covered 被挡住、option-not-found 没有这个选项），blockedBy 是挡住它的元素。\n   * effect 是动手前后页面的变化，selectedValues、availableOptions 是 select 的结果与可选项，controlState 是动完之后控件的值或勾选状态。\n   */\n  interface BrowserTargetActionResult {\n    action: BrowserTargetActionKind\n    url: string\n    matched: boolean\n    selector: string | null\n    text: string | null\n    clickPoint?: { x: number; y: number } | null | undefined\n    clickMethod?: ('dom' | 'coordinate') | null | undefined\n    effect?: BrowserTargetActionEffect | null | undefined\n    failureReason?: ('not-found' | 'not-interactable' | 'covered' | 'option-not-found') | null | undefined\n    blockedBy?: string | null | undefined\n    selectedValues?: string[] | null | undefined\n    availableOptions?: Array<{ value: string; text: string; selected: boolean }> | null | undefined\n    controlState?: ({\n      kind: 'text' | 'checkable' | 'select' | 'contenteditable'\n      value?: string | null | undefined\n      valueLength?: number | null | undefined\n      checked?: boolean | null | undefined\n      selectedValues?: string[] | null | undefined\n    }) | null | undefined\n    capturedAt: number\n  }\n\n  /** 点击没命中而改用坐标补点的记录：x、y 是补点的视口坐标，screenshotPath 是找坐标用的那张标注截图。 */\n  interface BrowserSelectorRecovery {\n    source: 'selector-coordinate-recovery'\n    screenshotPath: string\n    x: number\n    y: number\n  }\n\n  /** 点中了、页面却看不出变化时的提示：recommendedNextActions 是建议下一步做的（重新 inspect 或截图看看）。 */\n  interface BrowserActionEffectHint {\n    source: 'target-action-effect'\n    reason: 'no-observable-change'\n    recommendedNextActions: Array<'inspect' | 'screenshot'>\n  }\n\n  /** 导航动作：back、forward、reload、goto。 */\n  type BrowserPageNavigationAction = 'back' | 'forward' | 'reload' | 'goto'\n\n  /** 滚动方向：up、down、left、right、top（到顶）、bottom（到底）。 */\n  type BrowserPageScrollDirection = 'up' | 'down' | 'left' | 'right' | 'top' | 'bottom'\n\n  /** 组合键的修饰键：shift、control、alt、meta。 */\n  type BrowserKeyModifier = 'shift' | 'control' | 'alt' | 'meta'\n\n  /** 鼠标按键：left、middle、right。 */\n  type BrowserMouseButton = 'left' | 'middle' | 'right'\n\n  /** 拖拽的一端：matched 为假表示没找到这个元素，point 是按下或松开的位置。 */\n  interface BrowserDragEndpointResult {\n    matched: boolean\n    selector: string | null\n    text: string | null\n    point: { x: number; y: number } | null\n  }\n\n  /** 拖拽没成的原因：source-not-found、target-not-found、not-interactable。 */\n  type BrowserDragFailureReason = 'source-not-found' | 'target-not-found' | 'not-interactable'\n\n  /** 等 selector 到什么状态：attached（出现在文档里）、visible（看得见）、hidden（看不见）、detached（从文档里没了）。 */\n  type BrowserWaitForSelectorState = 'attached' | 'visible' | 'hidden' | 'detached'\n\n  /**\n   * 定位一个元素的线索（inspect、query、截图给的）：ref 是这次观察的引用（如 @e3:g2，新的一次 inspect 或标注截图之后作废），另有 css、role、text、name、attributes 与 frame。原样交给 click 这类操作就行。\n   */\n  interface BrowserElementTargetHint {\n    /** 来自一次页面 snapshot/inspection 的 generation 引用，如 @e3:g2；只对原 observation 有效。 */\n    ref?: string | null | undefined\n    css: string | null\n    role: string | null\n    text: string | null\n    name: string | null\n    frame?: BrowserElementFrameHint | null | undefined\n    attributes: Record<string, string>\n  }\n\n  /** 页面加载状态：domcontentloaded、load、networkidle（网络空闲）。 */\n  type BrowserPageWaitLoadState = 'domcontentloaded' | 'load' | 'networkidle'\n\n  /** 一个挂着等处理的事件：id 交给 handleDialog、handleDownload、handlePermission，details 里是弹窗文字、文件名、要的权限这些细节。 */\n  interface BrowserPendingEventSummary {\n    id: string\n    kind: BrowserPendingEventKind\n    createdAt: number\n    details: Record<string, unknown>\n  }\n\n  /** 挂起事件的种类：dialog（JS 弹窗）、download（下载）、permission（权限请求）。 */\n  type BrowserPendingEventKind = 'dialog' | 'download' | 'permission'\n\n  /** 列表里的一条：title 是标题（没有就取正文开头），href 是链接，description 是摘要。 */\n  interface BrowserListItem {\n    title: string\n    href: string | null\n    description: string | null\n  }\n\n  /** 正文的格式：plain 纯文本、markdown、html。 */\n  type BrowserPageContentFormat = 'plain' | 'markdown' | 'html'\n\n  /** 可以点的东西是什么：button、submit、link、combobox（下拉框）、option、menuitem。 */\n  type BrowserPageActionRole =\n    | 'button'\n    | 'submit'\n    | 'link'\n    | 'combobox'\n    | 'option'\n    | 'menuitem'\n\n  /** 紧凑快照从哪来：dom-inspection 或 cdp-accessibility（无障碍树）。 */\n  type BrowserPageSnapshotSource = 'dom-inspection' | 'cdp-accessibility'\n\n  /** 一个矩形（页面 CSS 像素）。 */\n  interface BrowserScreenshotRect {\n    x: number\n    y: number\n    width: number\n    height: number\n  }\n\n  /** 页面坐标与图上坐标怎么换算：图上的点乘 imageToPageScaleX、imageToPageScaleY 就是页面 CSS 像素；viewportRectInImage 是视口在图上的位置。clickAt 用的是视口坐标。 */\n  interface BrowserScreenshotModelCoordinateMap {\n    coordinateSpace: 'page-css-px'\n    pageToImageScaleX: number\n    pageToImageScaleY: number\n    imageToPageScaleX: number\n    imageToPageScaleY: number\n    viewportRectInImage: BrowserScreenshotRect\n    visibleViewport: BrowserScreenshotRect\n  }\n\n  /** 媒体种类：image、video、audio、other。 */\n  type BrowserMediaSourceKind = 'image' | 'video' | 'audio' | 'other'\n\n  /**\n   * 定位一个元素的线索，至少给一样：ref 是 inspect、标注截图给的引用（如 @e3:g2，原样传回；新的一次 inspect 或标注截图之后旧 ref 作废），\n   * css 是 CSS selector（最多 1000 个字符），text、name、role、attributes（id、data-testid 这类）按可见文字、可访问名称、角色与属性找；\n   * frame 限定在哪个同源 iframe 里找（只进一层）。inspect、query 结果里的 target 可以原样传进来。\n   */\n  interface BrowserTargetHint {\n    ref?: string | null | undefined\n    css?: string | null | undefined\n    role?: string | null | undefined\n    text?: string | null | undefined\n    name?: string | null | undefined\n    frame?: {\n      css?: string | null | undefined\n      name?: string | null | undefined\n      title?: string | null | undefined\n      url?: string | null | undefined\n    } | null | undefined\n    attributes?: Record<string, string>\n  }\n\n  /** 按元素动手的动作：click、fill、select、clear、select_all、scroll_into_view、focus、hover、check、uncheck。 */\n  type BrowserTargetActionKind =\n    | 'click'\n    | 'fill'\n    | 'select'\n    | 'clear'\n    | 'select_all'\n    | 'scroll_into_view'\n    | 'focus'\n    | 'hover'\n    | 'check'\n    | 'uncheck'\n\n  /** 动手前后页面的变化：observed 为真表示量到了，urlChanged、titleChanged、textChanged 说哪里变了。都没变时多半没点中想要的东西，重新 inspect 看看。 */\n  interface BrowserTargetActionEffect {\n    observed: boolean\n    urlChanged: boolean\n    titleChanged: boolean\n    textChanged: boolean\n    textDiff?: BrowserTargetActionTextDiff | null | undefined\n    before: BrowserTargetActionEffectSnapshot\n    after: BrowserTargetActionEffectSnapshot\n  }\n\n  /** 元素所在的同源 iframe：css、name、title、url 用来找到那个 iframe。 */\n  interface BrowserElementFrameHint {\n    css: string | null\n    name: string | null\n    title: string | null\n    url: string | null\n  }\n\n  /** 动手前后正文的差别：多了几行、少了几行、没变几行。 */\n  interface BrowserTargetActionTextDiff {\n    changed: boolean\n    additions: number\n    removals: number\n    unchanged: number\n    truncated: boolean\n  }\n\n  /** 动手前或动手后页面的一份指纹：地址、标题、正文的哈希与长度。 */\n  interface BrowserTargetActionEffectSnapshot {\n    url: string\n    title: string\n    textHash: string\n    textLength: number\n  }\n\n  /** 打开一个网站并进入它的站点（换网站就再 open 一次，各站点的工作区互不相通）。 */\n  export function open(input: BrowserOpenInput): Promise<BrowserOpened>\n\n  /** 退出站点：之后要页面的操作都要先 open；站点工作区里的文件留着。 */\n  export function leave(): Promise<void>\n\n  /** 看现在进没进站点、在哪一页（地址、标题、加载状态、最近一次导航错误）；没进站点时也能调。 */\n  export function state(): Promise<BrowserState>\n\n  /** 把受控页面显示出来给用户看，不执行任何脚本。 */\n  export function show(): Promise<BrowserPageWindowState>\n\n  /** 列出标签页：内嵌页面只有当前这一页，外部浏览器列出它的全部标签页。 */\n  export function tabs(): Promise<BrowserPageTargetsResult>\n\n  /** 把之后的操作切到外部浏览器的另一个标签页（不关闭任何窗口）。 */\n  export function switchTab(input: BrowserSwitchTabInput): Promise<BrowserSwitchPageTargetResult>\n\n  /** 看页面：正文、标题结构、链接、可交互元素与表单字段（元素带 target，可以直接交给 click 这类操作）。 */\n  export function inspect(input: BrowserInspectInput): Promise<BrowserPageInspection>\n\n  /** 按 CSS selector 找元素，读文字、属性、值与可见性；列表、表格、组件读法都走它。 */\n  export function query(input: BrowserQueryInput): Promise<BrowserElementQueryResult>\n\n  /** 截图：图交给你看，返回值是落盘位置、坐标换算与标注说明。能结构化读的（表格、列表、文字）别靠截图。 */\n  export function screenshot(input: BrowserScreenshotInput): Promise<BrowserScreenshot>\n\n  /** 在页面里跑一段 JavaScript，读专门操作覆盖不到的状态或调试页面。 */\n  export function evaluate(input: BrowserEvaluateInput): Promise<BrowserEvaluateScriptResult>\n\n  /** 列出页面上的图片、视频、音频地址；fetchable 为真的可以直接交给 download。 */\n  export function media(input: BrowserMediaInput): Promise<BrowserListMediaSourcesResult>\n\n  /** 点一个元素；没找到时如实回 matched 为假与原因，只在唯一确定的元素上改用坐标补点。 */\n  export function click(input: BrowserClickInput): Promise<BrowserActed>\n\n  /** 往输入框或可编辑区域写入文字。 */\n  export function fill(input: BrowserFillInput): Promise<BrowserActed>\n\n  /** 选原生 select 的选项（自定义下拉框先 click 打开，再重新 inspect 找选项）。 */\n  export function select(input: BrowserSelectInput): Promise<BrowserActed>\n\n  /** 勾选或取消勾选复选框、单选项。 */\n  export function check(input: BrowserCheckInput): Promise<BrowserActed>\n\n  /** 把鼠标移到元素中心（悬停出菜单、提示）。 */\n  export function hover(input: BrowserTargetInput): Promise<BrowserActed>\n\n  /** 聚焦一个元素（之后 type、press 落在它上面）。 */\n  export function focus(input: BrowserTargetInput): Promise<BrowserActed>\n\n  /** 清空输入框或可编辑区域。 */\n  export function clear(input: BrowserTargetInput): Promise<BrowserActed>\n\n  /** 选中输入框或可编辑区域里的全部文字。 */\n  export function selectText(input: BrowserTargetInput): Promise<BrowserActed>\n\n  /** 把元素滚到视口中间。 */\n  export function scrollIntoView(input: BrowserTargetInput): Promise<BrowserActed>\n\n  /** 在当前站点里跳到一个网址（换网站用 open）。 */\n  export function goto(input: BrowserGotoInput): Promise<BrowserPageNavigationResult>\n\n  /** 后退。 */\n  export function back(): Promise<BrowserPageNavigationResult>\n\n  /** 前进。 */\n  export function forward(): Promise<BrowserPageNavigationResult>\n\n  /** 刷新当前页。 */\n  export function reload(): Promise<BrowserPageNavigationResult>\n\n  /** 滚动页面（触发懒加载、看下面的内容）。 */\n  export function scroll(input: BrowserScrollInput): Promise<BrowserPageScrollResult>\n\n  /** 在当前焦点处输入文字。 */\n  export function type(input: BrowserTypeInput): Promise<BrowserTypeTextResult>\n\n  /** 按一个键或组合键（提交表单按 Enter）。 */\n  export function press(input: BrowserPressInput): Promise<BrowserPressKeyResult>\n\n  /** 把鼠标移到视口里的一个点。 */\n  export function mouseMove(input: BrowserPointInput): Promise<BrowserMoveMouseResult>\n\n  /** 按视口坐标点一下：定位不到元素时的兜底，坐标取自截图（按 image.coordinateMap 换算）。 */\n  export function clickAt(input: BrowserClickAtInput): Promise<BrowserClickCoordinatesResult>\n\n  /** 把一个元素拖到另一个元素上。 */\n  export function drag(input: BrowserDragInput): Promise<BrowserDragResult>\n\n  /** 给 file input 选一个站点工作区里的文件。 */\n  export function upload(input: BrowserUploadInput): Promise<BrowserUploadFileResult>\n\n  /** 等一个 selector 出现、可见、隐藏或消失。 */\n  export function waitForSelector(input: BrowserWaitForSelectorInput): Promise<BrowserWaitForSelectorResult>\n\n  /** 等页面正文里出现一段文字。 */\n  export function waitForText(input: BrowserWaitForTextInput): Promise<BrowserPageWaitResult>\n\n  /** 等地址变成某个样子（跳转、登录回调）。 */\n  export function waitForUrl(input: BrowserWaitForUrlInput): Promise<BrowserPageWaitResult>\n\n  /** 等页面里一个表达式变成真。 */\n  export function waitForFunction(input: BrowserWaitForFunctionInput): Promise<BrowserPageWaitResult>\n\n  /** 等页面加载到某个状态（networkidle 是网络空闲）。 */\n  export function waitForLoad(input: BrowserWaitForLoadInput): Promise<BrowserPageWaitResult>\n\n  /** 原地停一会儿。 */\n  export function wait(input: BrowserWaitInput): Promise<BrowserPageWaitResult>\n\n  /** 列出挂着等处理的弹窗、下载与权限请求；没人处理的会在超时后按缺省结算（弹窗取消、下载取消、权限拒绝）。 */\n  export function events(): Promise<BrowserPendingEventsResult>\n\n  /** 等一个挂起事件出现（点了下载按钮之后等下载事件，再 handleDownload）。 */\n  export function waitForEvent(input: BrowserWaitForEventInput): Promise<BrowserPendingEventWaitResult>\n\n  /** 处理 JS 弹窗（alert、confirm、prompt）。 */\n  export function handleDialog(input: BrowserDialogInput): Promise<BrowserHandleDialogResult>\n\n  /** 保存或取消一次下载。 */\n  export function handleDownload(input: BrowserDownloadDecisionInput): Promise<BrowserHandleDownloadResult>\n\n  /** 允许或拒绝一次权限请求。 */\n  export function handlePermission(input: BrowserPermissionInput): Promise<BrowserHandlePermissionResult>\n\n  /** 把页面上的一张表取成表头加各行。 */\n  export function table(input: BrowserTableInput): Promise<BrowserTable>\n\n  /** 把重复出现的条目（搜索结果、卡片）取成列表：标题、链接、摘要。 */\n  export function list(input: BrowserListInput): Promise<BrowserList>\n\n  /** 翻页收集列表（会真的点下一页）。 */\n  export function paginate(input: BrowserPaginateInput): Promise<BrowserPaginated>\n\n  /** 取页面正文（缺省 Markdown）。 */\n  export function content(input: BrowserContentInput): Promise<BrowserContent>\n\n  /** 带着当前页面的登录态下载一个资源到站点工作区。 */\n  export function download(input: BrowserDownloadInput): Promise<BrowserFetchResourceResult>\n\n  /** 把当前页面导出成 PDF。 */\n  export function savePdf(input: BrowserSavePdfInput): Promise<BrowserExportPagePdfResult>\n}\n",
  template: "// velar:browser 的代码模版：日常最常用的几种写法，一段一个函数。只是示例——按你的需要改写、只取其中几行都行，不必照着写。\n// 先 open 进站点；页面是异步的，动完用 waitFor 那几个等到位再读。元素写 inspect 给的 target、ref（@e3:g2）或 CSS selector。\nimport { click, content, fill, handleDownload, inspect, list, open, paginate, press, screenshot, table, waitForEvent, waitForLoad, waitForText } from 'velar:browser'\n\n// 打开一个网站，看看页面上有什么：标题、前几个小标题、可以点的东西。\nasync function look(url = 'https://example.com') {\n  await open({ url })\n  const page = await inspect({ maxTextChars: 4000 })\n  return {\n    title: page.title,\n    headings: page.headings.slice(0, 5).map((heading) => heading.text),\n    actions: page.actions.slice(0, 10).map((action) => ({ text: action.text, target: action.target })),\n  }\n}\n\n// 在站内搜索：找到搜索框填词、回车，等结果出来再按条取。\nasync function search(query = 'velaros') {\n  const page = await inspect({ maxElements: 100 })\n  const box = page.formFields.find((field) => field.type === 'search' || /search|搜索/i.test(field.label))\n  if (!box?.target) return { found: false }\n  await fill({ target: box.target, value: query })\n  await press({ key: 'Enter', waitForNavigation: true })\n  await waitForLoad({ state: 'networkidle' })\n  const results = await list({ selector: '.result', maxItems: 20 })\n  return { found: true, results: results.items }\n}\n\n// 填一张表单并提交：按标签找字段，填完点提交，等成功提示。\nasync function submitForm(values = { 邮箱: 'user@example.com', 姓名: '张三' }) {\n  const page = await inspect({})\n  for (const [label, value] of Object.entries(values)) {\n    const field = page.formFields.find((candidate) => candidate.label.includes(label))\n    if (field?.target) await fill({ target: field.target, value })\n  }\n  await click({ target: 'button[type=submit]' })\n  const done = await waitForText({ text: '提交成功', timeoutMs: 10000 })\n  return { submitted: done.matched }\n}\n\n// 看图定位：截一张带编号的图（图会交给你看），按编号对应的 target 去点。\nasync function clickByLook(label = '登录') {\n  const shot = await screenshot({ annotate: true })\n  const item = shot.legend?.find((entry) => entry.text?.includes(label))\n  if (!item) return { clicked: false, screenshot: shot.relativePath }\n  const result = await click({ target: item.target })\n  return { clicked: result.matched, screenshot: shot.relativePath }\n}\n\n// 把页面上的表格取出来。\nasync function readTable() {\n  const data = await table({ tableIndex: 0 })\n  return data.ok ? { headers: data.headers, rows: data.rows.slice(0, 50) } : { error: data.error }\n}\n\n// 翻页收集搜索结果（会真的点下一页，先确认在第一页）。\nasync function collect(selector = '.result') {\n  const pages = await paginate({ selector, maxPages: 3 })\n  return { pages: pages.pagesVisited, items: pages.items.map((item) => item.title) }\n}\n\n// 取正文读文章。\nasync function readArticle() {\n  const article = await content({ format: 'markdown', selector: 'article' })\n  return article.ok ? article.content.slice(0, 8000) : '这页上没找到正文'\n}\n\n// 点下载链接，等下载事件出来，存进站点工作区。\nasync function saveDownload(linkText = '下载报告', savePath = 'downloads/report.pdf') {\n  await click({ target: { text: linkText } })\n  const waited = await waitForEvent({ kind: 'download', timeoutMs: 10000 })\n  if (!waited.matched || !waited.event) return { saved: false }\n  const handled = await handleDownload({ eventId: waited.event.id, savePath })\n  return { saved: handled.handled, path: handled.savePath }\n}",
})

/** `velar:devtools` 的模型面：模型 import 的模块名、放出去的方法、生成的完整声明（与 baselines/code-surface/devtools.d.ts 是同一份）、代码模版（devtools-template.js）。 */
export const VelarDevtoolsModule: { readonly specifier: string; readonly namespace: string; readonly methods: readonly string[]; readonly declarations: string; readonly template: string } = Object.freeze({
  specifier: 'velar:devtools',
  namespace: 'devtools',
  methods: Object.freeze(['diagnostics', 'request', 'storage', 'setViewport', 'zoom', 'network', 'emulate', 'startTrace', 'stopTrace', 'insight', 'heapSnapshot', 'startRecording', 'stopRecording', 'userScripts', 'readUserScript', 'createUserScript', 'updateUserScript', 'enableUserScript', 'enableUserScripts', 'moveUserScript', 'deleteUserScript', 'runUserScript']),
  declarations: "declare module 'velar:devtools' {\n  /**\n   * 开发者工具：读控制台、网络与未处理异常，读一次请求的详情与响应体，读页面存储；改视口、缩放、网络条件与环境仿真；\n   * 录性能 trace 看 LCP、INP、CLS 与瓶颈，采堆快照查内存泄漏；录屏合成 GIF；管理进到匹配网站时自动注入的用户脚本。\n   * 都作用在 velar:browser 当前打开的站点上，没进站点时抛 BROWSER_SITE_NOT_OPEN。trace、堆快照、录屏的产物落在站点工作区。\n   */\n\n  /**\n   * 读诊断：kind 缺省 all；limit 是过滤之后最多几条（最多 300，不给就取到上限），clear 为真读完把这一类清掉。\n   * console 可按 level 或 errorsOnly 过滤；network 可按 status（100 到 999）、resourceType（最多 80 个字符）或 failedOnly 过滤，\n   * 回执里的 requestId 交给 request 读详情。\n   */\n  interface DevtoolsDiagnosticsInput {\n    kind?: BrowserPageDiagnosticsReadKind\n    limit?: number\n    clear?: boolean\n    level?: BrowserPageDiagnosticLevel\n    errorsOnly?: boolean\n    status?: number\n    resourceType?: string\n    failedOnly?: boolean\n  }\n\n  /** 读诊断的结果：kind 是 all 时是整份诊断，其余三类各是自己的形状。 */\n  type BrowserPageDiagnosticsReadResult =\n    | BrowserPageDiagnostics\n    | BrowserConsoleEventsResult\n    | BrowserNetworkEventsResult\n    | BrowserPageErrorsResult\n\n  /** 读一次网络请求的详情：requestId 取自 diagnostics 的网络条目（最多 200 个字符）；includeResponseBody 为真时带上响应体（maxBodyChars 最多 200000，不给就取到上限）。 */\n  interface DevtoolsRequestInput {\n    requestId: string\n    includeResponseBody?: boolean\n    maxBodyChars?: number\n  }\n\n  /** 一次请求的详情：request、response、failure 与总耗时；responseBody 只在 includeResponseBody 时有。 */\n  interface BrowserNetworkRequestDetailsResult {\n    url: string\n    requestId: string\n    request: BrowserNetworkRequestSnapshot\n    response: BrowserNetworkResponseSnapshot | null\n    failure: BrowserNetworkFailureSnapshot | null\n    durationMs: number | null\n    responseBody?: BrowserNetworkRequestResponseBodySnapshot\n    capturedAt: number\n  }\n\n  /**\n   * 读页面存储：localStorage 与 sessionStorage 缺省都读，cookie 要 includeCookies 为真才读；storageScope、cookieScope 选当前来源还是全部；\n   * limit 是每类最多几项（最多 300），maxValueChars 是每个值最多多少字符（最多 50000）。不给就取到上限。\n   */\n  interface DevtoolsStorageInput {\n    includeLocalStorage?: boolean\n    includeSessionStorage?: boolean\n    includeCookies?: boolean\n    storageScope?: BrowserStorageScope\n    cookieScope?: BrowserCookieScope\n    limit?: number\n    maxValueChars?: number\n  }\n\n  /** 页面存储：localStorage、sessionStorage、cookies 各是一组，origins 是按来源分开的存储。 */\n  interface BrowserPageStorageResult {\n    url: string\n    localStorage?: BrowserStorageEntry[]\n    sessionStorage?: BrowserStorageEntry[]\n    origins?: BrowserOriginStorage[]\n    cookies?: BrowserStorageEntry[]\n    capturedAt: number\n  }\n\n  /** 把视口设成指定尺寸（复现手机、平板布局）：宽 320 到 3840，高 240 到 2160，影响之后的截图与坐标。 */\n  interface DevtoolsViewportInput {\n    width: number\n    height: number\n  }\n\n  /** 设视口之后的尺寸。 */\n  interface BrowserViewportResult {\n    url: string\n    width: number\n    height: number\n    /** 实际应用的移动设备 viewport 语义；旧实现可能不返回此字段。 */\n    mobile?: boolean\n    capturedAt: number\n  }\n\n  /** 调页面缩放：action 是 in、out、reset、set；set 要给 zoomFactor（0.25 到 3），in、out 的步长 step 是 0.05 到 0.5。 */\n  interface DevtoolsZoomInput {\n    action: BrowserPageZoomAction\n    zoomFactor?: number\n    step?: number\n  }\n\n  /** 缩放之后的倍数：zoomFactor 是现在的，previousZoomFactor 是之前的。 */\n  interface BrowserPageZoomResult {\n    url: string\n    zoomFactor: number\n    previousZoomFactor: number\n    capturedAt: number\n  }\n\n  /**\n   * 设网络条件，至少给一样：offline 断网；extraHTTPHeaders 加请求头（名最多 120、值最多 4000 个字符）；\n   * blockedURLPatterns 拦这些地址（最多 100 条，每条最多 2048 个字符），blockedResourceTypes 拦这些资源类型（最多 32 种）；\n   * mockResponses 给匹配的请求直接回一个假响应（最多 50 条，正文最多 1000000 个字符）。\n   */\n  interface DevtoolsNetworkInput {\n    offline?: boolean\n    extraHTTPHeaders?: Record<string, string>\n    blockedURLPatterns?: string[]\n    blockedResourceTypes?: string[]\n    mockResponses?: BrowserNetworkMockResponse[]\n  }\n\n  /** 网络条件设好之后的全部状态：离线没有、加了哪些请求头、拦了哪些地址与资源类型、挂着哪些假响应。 */\n  interface BrowserNetworkControlResult {\n    url: string\n    offline: boolean\n    extraHTTPHeaders: Record<string, string>\n    blockedURLPatterns: string[]\n    blockedResourceTypes: string[]\n    mockResponses: BrowserNetworkMockResponse[]\n    capturedAt: number\n  }\n\n  /**\n   * 仿真环境，至少给一样：colorScheme 深浅色，reducedMotion 减少动效，timezoneId 时区（最多 120 个字符），locale 语言（最多 80 个字符），\n   * geolocation 地理位置，cpuThrottlingRate 是 CPU 降速几倍（1 到 20），networkThrottling 是网络节流档位。\n   */\n  interface DevtoolsEmulateInput {\n    colorScheme?: BrowserColorScheme\n    reducedMotion?: BrowserReducedMotion\n    timezoneId?: string\n    locale?: string\n    geolocation?: BrowserGeolocationOptions\n    cpuThrottlingRate?: number\n    networkThrottling?: BrowserNetworkThrottlingPreset\n  }\n\n  /** 仿真设好之后的全部状态：配色、动效、时区、语言、地理位置、CPU 降速倍数与网络节流档位。 */\n  interface BrowserEmulationResult {\n    url: string\n    colorScheme: BrowserColorScheme\n    reducedMotion: BrowserReducedMotion\n    timezoneId: string | null\n    locale: string | null\n    geolocation: BrowserGeolocationState | null\n    cpuThrottlingRate: number\n    networkThrottling: BrowserNetworkThrottlingPreset\n    capturedAt: number\n  }\n\n  /**\n   * 开始录性能 trace：reload 缺省 true（先重载，录完整加载）；autoStopMs 是录多久自动停并交回分析（缺省 5000，1000 到 60000），\n   * 给 null 就一直录到 stopTrace（录交互时这么用）。\n   */\n  interface DevtoolsTraceInput {\n    reload?: boolean\n    autoStopMs?: number | null | undefined\n  }\n\n  /** 开始录 trace 的结果：status 是 recording 时还在录（note 说怎么停），是 completed 时已经到点自动停、带着和 stopTrace 一样的分析。 */\n  type BrowserPerformanceTraceStartResult =\n    | {\n        status: 'recording'\n        url: string\n        startedAt: number\n        /** 给模型的操作提示：怎么停、能做什么。 */\n        note: string\n      }\n    | ({ status: 'completed' } & BrowserPerformanceTraceStopResult)\n\n  /**\n   * trace 的分析：keyMetrics 是各段的 Core Web Vitals（如 NAVIGATION_0: LCP 258 ms, CLS 0.00），summary 是整体摘要与可深入的 insight 清单，\n   * insightSetIds 交给 insight 的 insightSetId；原始 trace 落在 rawTracePath（.json.gz，能拖进 DevTools 的 Performance 面板）。\n   */\n  interface BrowserPerformanceTraceStopResult {\n    url: string\n    /** 每个 insight set 的 Core Web Vitals 紧凑摘要（如 `NAVIGATION_0: LCP 258 ms, CLS 0.00`），从完整 summary 里抽出来。 */\n    keyMetrics: string\n    /** DevTools trace 引擎生成的整体摘要（含 CWV 指标与可用 insight 清单）。 */\n    summary: string\n    /** 交给 insight 的 insightSetId 列表。 */\n    insightSetIds: string[]\n    /** 原始 trace 落盘绝对路径（.json.gz，可直接拖进 DevTools Performance 面板）。 */\n    rawTracePath: string\n    rawTraceRelativePath: string\n    durationMs: number\n    capturedAt: number\n  }\n\n  /** 对最近一次 trace 里的一条 insight 出详细分析：insightSetId 与 insightName 都取自 trace 摘要（各最多 120 个字符）。 */\n  interface DevtoolsInsightInput {\n    insightSetId: string\n    insightName: string\n  }\n\n  /** 一条 insight 的详细分析：output 是 DevTools 给的分析文字。 */\n  interface BrowserPerformanceInsightResult {\n    insightSetId: string\n    insightName: string\n    output: string\n    capturedAt: number\n  }\n\n  /** 采一份 V8 堆快照落进站点工作区：path 是相对路径（最多 300 个字符），不给就按时间命名。快照很大，别读进来，交给 memlab 这类工具分析。 */\n  interface DevtoolsHeapSnapshotInput {\n    path?: string\n  }\n\n  /** 堆快照的产物：落在 path，bytes 是大小。 */\n  interface BrowserHeapSnapshotResult {\n    url: string\n    path: string\n    relativePath: string\n    bytes: number\n    capturedAt: number\n  }\n\n  /** 开始录屏：maxWidth 是帧宽（240 到 1600，缺省 800），everyNthFrame 是每几帧取一帧（1 到 10，缺省 2）。页面不变不出新帧。 */\n  interface DevtoolsRecordingInput {\n    maxWidth?: number\n    everyNthFrame?: number\n  }\n\n  /** 开始录屏的结果：note 说怎么停。 */\n  interface BrowserScreencastStartResult {\n    url: string\n    status: 'recording'\n    startedAt: number\n    note: string\n  }\n\n  /** 停止录屏并合成 GIF：name 是产物名（最多 60 个字符），不给就按时间命名。 */\n  interface DevtoolsStopRecordingInput {\n    name?: string\n  }\n\n  /** 录屏的产物：GIF 落在 path（relativePath 是工作区里的相对路径），frameCount 是几帧，frameLimitReached 为真表示到帧数上限被截断。 */\n  interface BrowserScreencastStopResult {\n    url: string\n    /** GIF 落盘绝对路径。 */\n    path: string\n    relativePath: string\n    frameCount: number\n    durationMs: number\n    bytes: number\n    /** 达到帧数上限被自动截断。 */\n    frameLimitReached: boolean\n    capturedAt: number\n  }\n\n  /**\n   * 用户脚本操作的结果：overview 是操作之后的一览，script 是这次操作的那个脚本，code 是 readUserScript 读到的源码，run 是 runUserScript 的结果，refreshRequired 为真表示要刷新页面才能去掉已经执行过的效果。\n   */\n  interface BrowserUserScriptMutationResult {\n    overview: BrowserUserScriptOverview\n    script?: BrowserUserScriptRecord | null | undefined\n    code?: string | null | undefined\n    run?: BrowserUserScriptLastRun | null | undefined\n    /** 禁用脚本不会撤销已执行的页面副作用；需要刷新页面才能得到干净文档。 */\n    refreshRequired?: boolean | null | undefined\n  }\n\n  /** 指定一个用户脚本。 */\n  interface DevtoolsUserScriptIdInput {\n    id: string\n  }\n\n  /**\n   * 新建一个用户脚本（进到匹配的网站时自动注入的 JavaScript）：name 最多 120 个字符，code 最多 1000000 字节；\n   * match、excludeMatch 是网址规则（如 https://example.com/*，各最多 64 条、每条最多 500 个字符，只认 http 与 https），\n   * runAt 缺省 document-idle，world 缺省 isolated（只有要碰页面自己的 JavaScript 对象时才用 main）。\n   * 新建的脚本一律停用：先把 name、match、world、runAt 讲给用户，用户明确同意后再 enableUserScript。\n   */\n  interface DevtoolsCreateUserScriptInput {\n    name: string\n    code: string\n    description?: string\n    version?: string\n    match: string[]\n    excludeMatch?: string[]\n    runAt?: BrowserUserScriptRunAt\n    world?: BrowserUserScriptWorld\n  }\n\n  /** 改一个用户脚本，至少改一样；改了代码或执行范围之后脚本自动停用，要用户重新确认后再启用。上限同 createUserScript。 */\n  interface DevtoolsUpdateUserScriptInput {\n    id: string\n    name?: string\n    code?: string\n    description?: string\n    version?: string\n    match?: string[]\n    excludeMatch?: string[]\n    runAt?: BrowserUserScriptRunAt\n    world?: BrowserUserScriptWorld\n  }\n\n  /** 启用或停用一个用户脚本；未经用户明确同意不要启用。停用不会撤销当前页面已经执行的副作用，要刷新页面。 */\n  interface DevtoolsEnableUserScriptInput {\n    id: string\n    enabled: boolean\n  }\n\n  /** 用户脚本的总开关：为假时所有脚本都不注入。 */\n  interface DevtoolsEnableUserScriptsInput {\n    enabled: boolean\n  }\n\n  /** 调整注入顺序：把一个脚本往前（up）或往后（down）挪一位，越靠前越先执行。 */\n  interface DevtoolsMoveUserScriptInput {\n    id: string\n    direction: 'up' | 'down'\n  }\n\n  /** 读哪一类诊断：all 全部、console 控制台、network 网络请求、page_error 未处理的异常。 */\n  type BrowserPageDiagnosticsReadKind = 'all' | 'console' | 'network' | 'page_error'\n\n  /** 诊断的级别：debug、info、warning、error。 */\n  type BrowserPageDiagnosticLevel = 'debug' | 'info' | 'warning' | 'error'\n\n  /** 整份诊断：entries 是最近的条目（先按种类过滤再取窗口），summary 是计数，networkCaptureNotice 在网络采集这次才开始时出现。 */\n  interface BrowserPageDiagnostics {\n    url: string\n    title: string | null\n    entries: BrowserPageDiagnosticEntry[]\n    summary: BrowserPageDiagnosticsSummary\n    /**\n     * 网络采集的如实说明：内嵌页面的采集是读诊断时才建立的，这次才开始时要告诉模型\n     * 「之前的请求没有记录」，采集没能建立时要说清原因。没有要说的就不给这个字段。\n     */\n    networkCaptureNotice?: BrowserNetworkCaptureNotice\n    capturedAt: number\n  }\n\n  /** console 诊断：entries 是过滤后的条目，consoleTotal 是缓冲里 console 条目一共几条。 */\n  interface BrowserConsoleEventsResult {\n    url: string\n    title: string | null\n    entries: BrowserPageDiagnosticEntry[]\n    summary: BrowserPageDiagnosticsSummary\n    filters: BrowserConsoleEventFilters\n    diagnosticTotal: number\n    consoleTotal: number\n  }\n\n  /** 网络诊断：entries 带 requestId（交给 request 读详情）；networkCaptureNotice 在网络采集这次才开始时说明之前的请求看不到。 */\n  interface BrowserNetworkEventsResult {\n    url: string\n    title: string | null\n    entries: BrowserPageDiagnosticEntry[]\n    summary: BrowserPageDiagnosticsSummary\n    filters: BrowserNetworkEventFilters\n    diagnosticTotal: number\n    networkTotal: number\n    networkCaptureNotice: string | null\n  }\n\n  /** 未处理异常的诊断。 */\n  interface BrowserPageErrorsResult {\n    url: string\n    title: string | null\n    entries: BrowserPageDiagnosticEntry[]\n    summary: BrowserPageDiagnosticsSummary\n    diagnosticTotal: number\n    pageErrorTotal: number\n  }\n\n  /** 请求：method、url、headers、postData、resourceType 与发出的时间。 */\n  interface BrowserNetworkRequestSnapshot {\n    method: string\n    url: string\n    headers: Record<string, string>\n    postData?: string\n    resourceType: string\n    timestamp: number | null\n    wallTime: number | null\n  }\n\n  /** 响应：status、statusText、headers、mimeType、协议，是不是来自缓存或 Service Worker，体积与对端地址，timing 是各阶段耗时。 */\n  interface BrowserNetworkResponseSnapshot {\n    status: number\n    statusText: string\n    headers: Record<string, string>\n    mimeType: string | null\n    protocol: string | null\n    fromDiskCache: boolean\n    fromServiceWorker: boolean\n    encodedDataLength: number | null\n    remoteIPAddress: string | null\n    remotePort: number | null\n    timing: Record<string, unknown> | null\n  }\n\n  /** 请求失败：errorText 是原因，canceled 为真表示被取消。 */\n  interface BrowserNetworkFailureSnapshot {\n    errorText: string\n    canceled: boolean\n  }\n\n  /** 响应体：body 是内容（base64Encoded 为真时是 base64），bodyLength 是原长，bodyTruncated 为真表示只交回了一部分。 */\n  interface BrowserNetworkRequestResponseBodySnapshot {\n    body: string\n    base64Encoded: boolean\n    bodyLength: number\n    returnedChars: number\n    bodyTruncated: boolean\n  }\n\n  /** 存储读哪儿：current-origin 当前来源，all-origins 页面里所有来源（外部浏览器才有）。 */\n  type BrowserStorageScope = 'current-origin' | 'all-origins'\n\n  /** cookie 读哪些：current-url 当前地址会带的，all 这个浏览器里的全部。 */\n  type BrowserCookieScope = 'current-url' | 'all'\n\n  /** 一项存储或 cookie：name、value（valueTruncated 为真表示值被截断），details 里是 cookie 的域、路径、过期时间这些。 */\n  interface BrowserStorageEntry {\n    name: string\n    value: string\n    valueTruncated: boolean\n    details?: Record<string, unknown>\n  }\n\n  /** 一个来源的 localStorage 与 sessionStorage。 */\n  interface BrowserOriginStorage {\n    origin: string\n    localStorage?: BrowserStorageEntry[]\n    sessionStorage?: BrowserStorageEntry[]\n  }\n\n  /** 缩放动作：in 放大、out 缩小、reset 还原、set 设成指定倍数。 */\n  type BrowserPageZoomAction = 'in' | 'out' | 'reset' | 'set'\n\n  /** 一条假响应：urlPattern 匹配的请求直接回这里的 status（缺省 200）、contentType、body 与 headers，不再发到服务器。 */\n  interface BrowserNetworkMockResponse {\n    urlPattern: string\n    status?: number\n    contentType?: string\n    body?: string\n    headers?: Record<string, string>\n  }\n\n  /** 配色：light、dark、no-preference。 */\n  type BrowserColorScheme = 'light' | 'dark' | 'no-preference'\n\n  /** 动效偏好：reduce 减少动效，no-preference 不限。 */\n  type BrowserReducedMotion = 'reduce' | 'no-preference'\n\n  /** 地理位置：latitude 纬度（-90 到 90），longitude 经度（-180 到 180），accuracy 精度（米）。 */\n  interface BrowserGeolocationOptions {\n    latitude: number\n    longitude: number\n    accuracy?: number\n  }\n\n  /** 网络节流档位：none 不节流，slow-3g、fast-3g、slow-4g、fast-4g 与 DevTools 的 Network conditions 同一套数值。 */\n  type BrowserNetworkThrottlingPreset = 'none' | 'slow-3g' | 'fast-3g' | 'slow-4g' | 'fast-4g'\n\n  /** 当前仿真的地理位置。 */\n  interface BrowserGeolocationState {\n    latitude: number\n    longitude: number\n    accuracy: number\n  }\n\n  /** 用户脚本一览：globalEnabled 是总开关，scripts 是全部脚本，matchedScriptIds 是匹配当前页面的那几个。 */\n  interface BrowserUserScriptOverview {\n    browserContext: BrowserSiteContext\n    globalEnabled: boolean\n    scripts: BrowserUserScriptRecord[]\n    /** 匹配当前页面的脚本 id（按宿主的匹配规则针对 browserContext.url 算出）。 */\n    matchedScriptIds: string[]\n  }\n\n  /** 一个用户脚本：id、name、match 与 excludeMatch 是网址规则，runAt、world 是注入时机与环境，enabled 是启没启用，position 是注入顺序（越小越先），lastRun 是最近一次运行。 */\n  interface BrowserUserScriptRecord {\n    id: string\n    name: string\n    description?: string | null | undefined\n    version: string\n    /** 宿主维护的执行修订号，用于 document + revision 幂等注入。 */\n    revision: number\n    /** 注入顺序，数字越小越先执行。 */\n    position: number\n    match: string[]\n    excludeMatch?: string[] | null | undefined\n    runAt: BrowserUserScriptRunAt\n    world: BrowserUserScriptWorld\n    enabled: boolean\n    source: BrowserUserScriptSource\n    relativePath: string\n    createdAt: number\n    updatedAt: number\n    lastRun?: BrowserUserScriptLastRun | null | undefined\n  }\n\n  /** 用户脚本最近一次自动注入或手动运行：在哪个页面（url）、第几版脚本（scriptRevision）、结果与出错信息。 */\n  interface BrowserUserScriptLastRun {\n    status: BrowserUserScriptRunStatus\n    url: string\n    documentId: string\n    scriptRevision: number\n    startedAt: number\n    finishedAt: number\n    error?: string | null | undefined\n  }\n\n  /** 用户脚本在页面加载的哪个时机注入：document-start、document-end、document-idle。 */\n  type BrowserUserScriptRunAt = 'document-start' | 'document-end' | 'document-idle'\n\n  /** 用户脚本跑在哪：isolated 是隔离环境（缺省，碰不到页面自己的 JavaScript 对象），main 是页面自己的环境。 */\n  type BrowserUserScriptWorld = 'isolated' | 'main'\n\n  /**\n   * 一条诊断：message 是内容，url、line、column 是出处，code 是 HTTP 状态这类数字；网络条目的 details 里有 requestId（交给 request 读详情）、method、status、resourceType。\n   */\n  interface BrowserPageDiagnosticEntry {\n    kind: BrowserPageDiagnosticKind\n    level: BrowserPageDiagnosticLevel\n    message: string\n    url: string | null\n    line: number | null\n    column: number | null\n    code: number | null\n    capturedAt: number\n    details?: Record<string, unknown>\n  }\n\n  /** 诊断的计数：按级别、种类、来源、HTTP 状态、资源类型各数了几条。 */\n  interface BrowserPageDiagnosticsSummary {\n    total: number\n    byLevel: Record<string, number>\n    byKind: Record<string, number>\n    byOrigin: Record<string, number>\n    byStatus: Record<string, number>\n    byResourceType: Record<string, number>\n  }\n\n  /** 网络采集的说明：这次才开始采集时告诉你之前的请求没有记录，采集没能开始时说原因。 */\n  type BrowserNetworkCaptureNotice = string | null | undefined\n\n  /** console 这一类的过滤条件。 */\n  interface BrowserConsoleEventFilters {\n    level: BrowserPageDiagnosticLevel | null\n    errorsOnly: boolean\n  }\n\n  /** network 这一类的过滤条件。 */\n  interface BrowserNetworkEventFilters {\n    status: number | null\n    resourceType: string | null\n    failedOnly: boolean\n  }\n\n  /** 站点：url 是进站时的地址，workspaceRoot 是这个站点的工作区（截图、下载、PDF 都落在这里），legacyWorkspaceRoots 是只读的旧工作区（读不到时依次往回找）。 */\n  interface BrowserSiteContext {\n    url: string\n    /** 站点工作区根：写入的唯一落点（粒度由宿主定）。 */\n    workspaceRoot: string\n    /**\n     * 只读的历史工作区根（换粒度前留下的资产），按新到旧排列：写只写 workspaceRoot，读不到才依次回退。\n     * 不做一次性搬迁——回退读是幂等的，用户每碰一次旧资产就自然继续可用，新写入自动落到新位置。\n     */\n    legacyWorkspaceRoots?: readonly string[]\n  }\n\n  /** 用户脚本是谁建的：agent（你建的）、user、user-import。 */\n  type BrowserUserScriptSource = 'agent' | 'user' | 'user-import'\n\n  /** 一次注入或运行的结果：success、error、unsupported（当前后端做不到，比如外部浏览器）。 */\n  type BrowserUserScriptRunStatus = 'success' | 'error' | 'unsupported'\n\n  /** 诊断的种类：console、page-error（未处理的异常）、load-error、render-process-gone、download、popup、permission、dialog、network、storage。 */\n  type BrowserPageDiagnosticKind =\n    | 'console'\n    | 'page-error'\n    | 'load-error'\n    | 'render-process-gone'\n    | 'download'\n    | 'popup'\n    | 'permission'\n    | 'dialog'\n    | 'network'\n    | 'storage'\n\n  /** 读诊断：先按种类过滤再取最近的几条，网络条目带 requestId。 */\n  export function diagnostics(input: DevtoolsDiagnosticsInput): Promise<BrowserPageDiagnosticsReadResult>\n\n  /** 读一次网络请求的请求头、postData、响应头、耗时与体积，可带响应体；较早的请求可能已经读不到。 */\n  export function request(input: DevtoolsRequestInput): Promise<BrowserNetworkRequestDetailsResult>\n\n  /** 读页面的 localStorage、sessionStorage 与 cookie。 */\n  export function storage(input: DevtoolsStorageInput): Promise<BrowserPageStorageResult>\n\n  /** 把视口设成指定尺寸。 */\n  export function setViewport(input: DevtoolsViewportInput): Promise<BrowserViewportResult>\n\n  /** 调页面缩放。 */\n  export function zoom(input: DevtoolsZoomInput): Promise<BrowserPageZoomResult>\n\n  /** 设网络条件：断网、加请求头、拦请求、给请求回假响应。 */\n  export function network(input: DevtoolsNetworkInput): Promise<BrowserNetworkControlResult>\n\n  /** 仿真环境：深浅色、减少动效、时区、语言、地理位置、CPU 与网络节流。 */\n  export function emulate(input: DevtoolsEmulateInput): Promise<BrowserEmulationResult>\n\n  /** 开始录性能 trace；到点自动停时直接交回分析摘要。 */\n  export function startTrace(input: DevtoolsTraceInput): Promise<BrowserPerformanceTraceStartResult>\n\n  /** 停止录 trace，交回 Core Web Vitals 与可深入分析的 insight 清单；原始 trace 落在站点工作区。 */\n  export function stopTrace(): Promise<BrowserPerformanceTraceStopResult>\n\n  /** 对最近一次 trace 的一条 insight 出详细分析。 */\n  export function insight(input: DevtoolsInsightInput): Promise<BrowserPerformanceInsightResult>\n\n  /** 采一份 V8 堆快照落盘（按「基线、操作、回退」各采一份对比着查泄漏）。 */\n  export function heapSnapshot(input: DevtoolsHeapSnapshotInput): Promise<BrowserHeapSnapshotResult>\n\n  /** 开始录屏：之后的页面操作都录下来，stopRecording 合成 GIF。 */\n  export function startRecording(input: DevtoolsRecordingInput): Promise<BrowserScreencastStartResult>\n\n  /** 停止录屏并合成 GIF 落进站点工作区（帧数到上限会自动截断，frameLimitReached 为真）。 */\n  export function stopRecording(input: DevtoolsStopRecordingInput): Promise<BrowserScreencastStopResult>\n\n  /** 列出全部用户脚本、总开关，以及哪些脚本匹配当前页面。 */\n  export function userScripts(): Promise<BrowserUserScriptMutationResult>\n\n  /** 读一个用户脚本，带源码。 */\n  export function readUserScript(input: DevtoolsUserScriptIdInput): Promise<BrowserUserScriptMutationResult>\n\n  /** 新建一个用户脚本（一律先停用）。 */\n  export function createUserScript(input: DevtoolsCreateUserScriptInput): Promise<BrowserUserScriptMutationResult>\n\n  /** 改一个用户脚本。 */\n  export function updateUserScript(input: DevtoolsUpdateUserScriptInput): Promise<BrowserUserScriptMutationResult>\n\n  /** 启用或停用一个用户脚本。 */\n  export function enableUserScript(input: DevtoolsEnableUserScriptInput): Promise<BrowserUserScriptMutationResult>\n\n  /** 打开或关闭用户脚本的总开关。 */\n  export function enableUserScripts(input: DevtoolsEnableUserScriptsInput): Promise<BrowserUserScriptMutationResult>\n\n  /** 调整一个用户脚本的注入顺序。 */\n  export function moveUserScript(input: DevtoolsMoveUserScriptInput): Promise<BrowserUserScriptMutationResult>\n\n  /** 删掉一个用户脚本（不撤销当前页面已经执行的副作用）。 */\n  export function deleteUserScript(input: DevtoolsUserScriptIdInput): Promise<BrowserUserScriptMutationResult>\n\n  /** 在当前页面立刻跑一次某个用户脚本。 */\n  export function runUserScript(input: DevtoolsUserScriptIdInput): Promise<BrowserUserScriptMutationResult>\n}\n",
  template: "// velar:devtools 的代码模版：排障、调页面时最常用的几种写法，一段一个函数。只是示例——按你的需要改写、只取其中几行都行，不必照着写。\n// 都作用在 velar:browser 当前打开的站点上，先 open。trace、堆快照、录屏的产物落在站点工作区。\nimport { createUserScript, diagnostics, emulate, insight, network, request, setViewport, startRecording, startTrace, stopRecording, storage } from 'velar:devtools'\n\n// 页面报错了：看最近的控制台错误与未处理异常，读完把这一类清掉。\nasync function consoleErrors() {\n  const errors = await diagnostics({ kind: 'console', errorsOnly: true, limit: 20, clear: true })\n  return errors.entries.map((entry) => ({ level: entry.level, message: entry.message, url: entry.url }))\n}\n\n// 接口失败了：找失败的请求，读第一个的详情与响应体。\nasync function failedRequests() {\n  const failed = await diagnostics({ kind: 'network', failedOnly: true, limit: 20 })\n  const first = failed.entries[0]\n  const requestId = first?.details?.requestId\n  if (typeof requestId !== 'string') return { failures: failed.entries.length }\n  const detail = await request({ requestId, includeResponseBody: true, maxBodyChars: 4000 })\n  return { failures: failed.entries.length, first: { status: detail.response?.status, body: detail.responseBody?.body } }\n}\n\n// 页面加载慢：录一次完整加载，拿 Core Web Vitals，再深入看第一条 insight。\nasync function measureLoad() {\n  const trace = await startTrace({ reload: true, autoStopMs: 5000 })\n  if (trace.status !== 'completed') return { note: trace.note }\n  const setId = trace.insightSetIds[0]\n  const detail = setId ? await insight({ insightSetId: setId, insightName: 'LCPBreakdown' }) : null\n  return { metrics: trace.keyMetrics, lcp: detail?.output.slice(0, 3000) }\n}\n\n// 复现手机上的深色布局：设视口与配色，再回 velar:browser 截图看。\nasync function mobileDark() {\n  await setViewport({ width: 390, height: 844 })\n  await emulate({ colorScheme: 'dark' })\n  return '视口与配色已设好，接着用 velar:browser 的 screenshot 看效果'\n}\n\n// 断网或给接口回假数据，看页面怎么降级。\nasync function mockApi(urlPattern = '*/api/profile*') {\n  await network({ mockResponses: [{ urlPattern, status: 500, contentType: 'application/json', body: '{\"error\":\"boom\"}' }] })\n  return '之后匹配的请求都会拿到 500，刷新页面看效果；恢复就再调一次 network 清掉'\n}\n\n// 看页面存了什么：localStorage、sessionStorage 与 cookie。\nasync function peekStorage() {\n  const stored = await storage({ includeCookies: true, limit: 50 })\n  return { local: stored.localStorage?.map((item) => item.name), cookies: stored.cookies?.map((item) => item.name) }\n}\n\n// 录下一段操作：开始录，做完操作再停，GIF 落在站点工作区。\nasync function record(name = 'checkout-flow') {\n  await startRecording({ maxWidth: 800 })\n  // ……这里用 velar:browser 做要录的操作……\n  const gif = await stopRecording({ name })\n  return { path: gif.relativePath, frames: gif.frameCount }\n}\n\n// 新建一个进站就自动跑的用户脚本：先停用存着，讲给用户听，用户同意后再 enableUserScript。\nasync function hidePopup() {\n  const created = await createUserScript({\n    name: '隐藏订阅弹窗',\n    code: \"document.querySelector('[data-newsletter-popup]')?.remove()\",\n    match: ['https://example.com/*'],\n    runAt: 'document-end',\n  })\n  return { id: created.script?.id, enabled: created.script?.enabled }\n}",
})
